  panel.append(title, help, info);
  button('Mở rộng ↑', () => { if (selected?.parentElement && selected !== document.body) { history.push(selected); paint(selected.parentElement); } });
  button('Thu hẹp ↓', () => { if (history.length) paint(history.pop()); });
